from datetime import datetime, timedelta
from wildlife.store import Store
import pytest


def test_explicit_now():
    s = Store()
    now = datetime(2026, 1, 1, 12)
    s.add("zebra", now - timedelta(hours=1))
    s.add("zebra", now - timedelta(hours=30))
    assert recent_count(s, now=now) == 1


def test_default_cutoff_uses_utc(monkeypatch):
    from datetime import timezone
    import wildlife.stats as stats

    class FakeDT(datetime):
        @classmethod
        def now(cls, tz=None):
            if tz is None:
                raise AssertionError("now() called without UTC tz")
            return datetime(2026, 1, 1, 12, tzinfo=timezone.utc)

    monkeypatch.setattr(stats, "datetime", FakeDT)
    s = Store()
    s.add("zebra", datetime(2026, 1, 1, 11))
    assert stats.recent_count(s) == 1
    assert stats._cutoff(24) == datetime(2026, 1, 1, -12)

